// Exportar na aba atual, no formato escolhido
btnExportar.onclick = () => {
  const itens = Store.all(abaAtual);
  if (!itens.length) return toast('Nada para exportar.', 'aviso');
  const fmt = exportFormat.value;
  const cols = [...new Set(itens.flatMap(o => Object.keys(o)))];
  const baixar = (conteudo, mime, ext) => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([conteudo], { type: mime }));
    a.download = abaAtual + '.' + ext; a.click();
    toast('Arquivo .' + ext + ' exportado!');
  };
  if (fmt === 'csv') {
    const csv = [cols.join(','), ...itens.map(o => cols.map(c => `"${String(o[c] ?? '').replace(/"/g, '""')}"`).join(','))].join('\n');
    baixar('\uFEFF' + csv, 'text/csv;charset=utf-8', 'csv');
  } else if (fmt === 'doc') {
    const html = `<html><head><meta charset="utf-8"></head><body><h1>${abaAtual}</h1>` +
      itens.map(o => `<h3>${esc(o[ENT[abaAtual].keyNome])}</h3><p>${cols.map(c => `<b>${c}:</b> ${esc(o[c])}`).join('<br>')}</p><hr>`).join('') + '</body></html>';
    baixar('\uFEFF' + html, 'application/msword', 'doc');
  } else if (fmt === 'txt') {
    baixar(itens.map(o => cols.map(c => `${c}: ${o[c]}`).join('\n')).join('\n\n---\n\n'), 'text/plain;charset=utf-8', 'txt');
  } else {
    baixar(JSON.stringify(itens, null, 2), 'application/json', 'json');
  }
};

