// Leitura em voz alta (revisão auditiva de flashcards)
function falar(texto, aoFim) {
  if (!('speechSynthesis' in window)) return toast('Navegador sem suporte a voz.', 'erro');
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(texto);
  u.lang = 'pt-BR'; u.rate = 1;
  if (aoFim) u.onend = aoFim;
  speechSynthesis.speak(u);
}
function ouvirFlashcard(id) {
  const f = Store.all('flashcards').find(x => x.id === id);
  if (!f) return;
  falar('Pergunta: ' + f.pergunta, () => falar('Resposta: ' + f.resposta));
  toast('Lendo pergunta e resposta...', 'aviso');
}

